--Program: Safe Kitchen Functions

go
package main
import ("errors"; "fmt")

func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, errors.New("cannot divide by 0 — check stock")
	}
	return a / b, nil
}

func calc(a, b int) (sum int, prod int) {
	sum = a b
	prod = a b
	return
}

func average(nums ...float64) float64 {
	total := 0.0
	for _, n := range nums {
		total += n
	}
	if len(nums) == 0 {
		return 0
	}
	return total / float64(len(nums))
}

// panic = emergency alarm, recover = extinguish (à la Effective Go!)
func safeSell(stock int) {
	defer func() {
		if r := recover(); r != nil { // catch panic!
			fmt.Println("Saved! panic caught:", r)
		}
	}()
	if stock < 0 {
		panic("negative stock!") // sound alarm
	}
	fmt.Println("Sell, left:", stock)
}

func main() {
	defer fmt.Println("Done — defer runs last")
	safeSell(5)
	safeSell(-1) // panic → caught → program CONTINUES!
	result, err := divide(10, 2)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		fmt.Printf("10/2 = %.1f\n", result)
	}
	_, err = divide(5, 0)
	if err != nil {
		fmt.Println("Divide 0 error:", err)
	}
	j, k := calc(4, 5)
	fmt.Printf("Sum %d, Prod %d\n", j, k)
	fmt.Printf("Average: %.1f\n", average(80, 90, 75))
}
