Without auth, anyone  wipes everything. With JWT in , the server knows who rejects non-owners.

--Program: GraphQL Shop ID

javascript
const jwt = require("jsonwebtoken");
const SECRET = "shop-secret";

// Login → token
const resolvers = {
  Mutation: {
    login: (_, { email, password }) => {
      if (email === "admin@shop.com" && password === "123") {
        const token = jwt.sign({ email, role: "admin" }, SECRET);
        return { token };
      }
      throw new Error("Wrong");
    },
    addProduct: (_, { input }, context) => {
      if (!context.user) throw new Error("Login first!"); // guard
      return { id: "9", ...input };
    },
  },
};

// Server reads ID every request
const server = new ApolloServer({
  typeDefs, resolvers,
  context: ({ req }) => {
    const token = (req.headers.authorization || "").replace("Bearer ", "");
    try {
      return { user: jwt.verify(token, SECRET) }; // valid ID?
    } catch { return {}; } // no ID
  },
});
