Performance Optimization

Kategori: JavaScript  Minggu 13: Performance Optimization
Prerequisites: Week 12 — Testing JavaScript.

Learning Objectives

Debounce: delay execution until the user stops
Throttle: limit execution rate
Memoization: cache expensive function results
Lazy loading: load resources when needed
Web Workers: heavy computation on a separate thread

--Why This Matters (Non-IT)

A 1000-item list without / = gasping on a potato phone. With split cache search, 5 seconds → 0.--Program: Performance Optimization

javascript
// Debounce
function debounce(fn, delay) {
    let timer;
    return function(...args) {
        clearTimeout(timer);
        timer = setTimeout(() => fn.apply(this, args), delay);
    };
}

// Throttle
function throttle(fn, limit) {
    let inThrottle = false;
    return function(...args) {
        if (!inThrottle) {
            fn.apply(this, args);
            inThrottle = true;
            setTimeout(() => inThrottle = false, limit);
        }
    };
}

// Memoization
function memoize(fn) {
    const cache = new Map();
    return function(...args) {
        const key = JSON.stringify(args);
        if (cache.has(key)) {
            console.log("  Cache hit for", key);
            return cache.get(key);
        }
        const result = fn.apply(this, args);
        cache.set(key, result);
        return result;
    };
}

// Lazy Loading Pattern
