Performance Optimization

Kategori: JavaScript  Minggu 13: Performance Optimization
Prasyarat: Minggu 12 — Testing JavaScript.

Tujuan Pembelajaran

Debounce: delay execution sampai user berhenti
Throttle: limit execution rate
Memoization: cache hasil fungsi mahal
Lazy loading: load resources saat dibutuhkan
Web Workers: heavy computation di thread terpisah

--Kenapa Ini Penting Buat Kamu?

Daftar 1000 tanpa / = ngos-ngosan di HP kentang. Dengan split cache cari, 5 detik → 0.--Program: Optimasi Performa

javascript
// Debounce
function debounce(fn, delay) {
    let timer;
    return function(...args) {
        clearTimeout(timer);
        timer = setTimeout(() => fn.apply(this, args), delay);
    };
}

// Throttle
function throttle(fn, limit) {
    let inThrottle = false;
    return function(...args) {
        if (!inThrottle) {
            fn.apply(this, args);
            inThrottle = true;
            setTimeout(() => inThrottle = false, limit);
        }
    };
}

// Memoization
function memoize(fn) {
    const cache = new Map();
    return function(...args) {
        const key = JSON.stringify(args);
        if (cache.has(key)) {
            console.log("  Cache hit for", key);
            return cache.get(key);
        }
        const result = fn.apply(this, args);
        cache.set(key, result);
        return result;
    };
}

// Lazy Loading Pattern
class LazyImage {
    constructor(src) {
        this.src = src;
        this.loaded = false;
    }

    load() {
        if (this.loaded) return;
        console.log("Loading:", this.src);
        this.loaded = true;
    }
}

